package io.b2mash.b2b.b2bstrawman.verticals.legal.statement.dto;

import java.math.BigDecimal;

/**
 * Numeric summary block of a Statement of Account (architecture §67.4.3 / §67.6.1). Mirrors the six
 * summary lines rendered in the template + the response payload's {@code summary} object.
 *
 * <p>{@code trustWithheld} (CodeRabbit #5 / G89-F51): the trust figure is not available to this
 * reader — the statement was generated by a member without VIEW_TRUST (nothing was read, so there
 * is no figure), or the caller reading it lacks VIEW_TRUST. Then {@code trustBalanceHeld} is {@code
 * null}, never a zero that would read as "no trust money held". A genuine zero (trust visible, no
 * trust activity) is {@code trustWithheld = false} with {@code trustBalanceHeld = 0}.
 */
public record StatementSummary(
    BigDecimal totalFees,
    BigDecimal totalDisbursements,
    BigDecimal previousBalanceOwing,
    BigDecimal paymentsReceived,
    BigDecimal closingBalanceOwing,
    BigDecimal trustBalanceHeld,
    boolean trustWithheld) {

  /** A summary whose trust figure is available ({@code trustWithheld = false}). */
  public StatementSummary(
      BigDecimal totalFees,
      BigDecimal totalDisbursements,
      BigDecimal previousBalanceOwing,
      BigDecimal paymentsReceived,
      BigDecimal closingBalanceOwing,
      BigDecimal trustBalanceHeld) {
    this(
        totalFees,
        totalDisbursements,
        previousBalanceOwing,
        paymentsReceived,
        closingBalanceOwing,
        trustBalanceHeld,
        false);
  }

  /** This summary with its trust figure withheld: no balance, {@code trustWithheld = true}. */
  public StatementSummary withTrustWithheld() {
    return new StatementSummary(
        totalFees,
        totalDisbursements,
        previousBalanceOwing,
        paymentsReceived,
        closingBalanceOwing,
        null,
        true);
  }
}
